int64_t res = (int64_t)a - b;
uint8_t round = get_round(vxrm, res, 1);
return (res >> 1) + round;

int64_t res = (int64_t)a - b;
int64_t over = (res ^ a) & (a ^ b) & INT64_MIN;
return ((res >> 1) ^ over) + round;

int64_t res = (int64_t)a - b;
